dtsPropsFor.AppShell:
/** 로그인한 의료인 — 사이드바 하단에 이름·소속 한의원으로 표시된다. */
me: {
  id: string;
  email: string;
  displayName: string;
  clinic: { id: string; name: string };
  verificationStatus: "PENDING" | "VERIFIED" | "REJECTED";
};
/** 우측 main 영역에 렌더되는 페이지 본문. */
children: React.ReactNode;

dtsPropsFor.EvidenceInspector:
/** 인용 근거 목록. marker 가 있으면 그 번호를, 없으면 배열 순서(index + 1)를 마커로 쓴다 (§8).
 * 스트림 근거(EvidenceDetailResponseDto)는 구조적 부분집합이라 그대로 대입된다. */
evidence: {
  /** EvidenceChunk id — 카드의 "전문 보기" 가 GET /evidence/{id} 로 전문을 조회한다. */
  id: string;
  guidelineTitle: string;
  /** @example "2.0" */
  version: string;
  /** 지침 내 섹션 경로 — UI 에서 " > " 로 이어 붙인다. */
  sectionPath: string[];
  /** 카드 요약 발췌 — 3줄 클램프로 표시된다. */
  excerpt: string;
  recommendationGrade?: { system: string; code: string; label: string };
  /** 명시 마커 — 저장된 메시지의 인용 경로가 넘긴다. 없으면 index + 1 이 마커다. */
  marker?: number;
  /** EvidenceDetailResponseDto 의 나머지 필드(guidelineId 등)는 그대로 넘겨도 되며 렌더에 쓰지 않는다. */
}[];
/** 강조할 마커 번호. null 이면 선택 없음. */
activeMarker: number | null;
onSelectMarker: (marker: number) => void;

dtsPropsFor.GuidanceCard:
/** 임상 참고안. reviewStatus 가 "DRAFT" 일 때만 하단 검토 폼이 렌더된다. */
guidance: {
  id: string;
  patientId: string;
  patientProfileSnapshotId: string;
  /** 참고안 요약 — 개행이 보존되어 표시된다. */
  summary: string;
  considerations: { title: string; rationale: string; citations: { marker: number; evidenceId: string; guidelineTitle: string; guidelineVersion: string; sectionPath: string[]; quote: string; sourceUrl: string }[]; /** 근거 조건과 환자 프로필이 만나는 지점의 적용 판단 — 구조화 경로에서만 실린다. */ applicability?: "APPLICABLE" | "CAUTION" | "NOT_APPLICABLE"; /** 이 판단이 딛고 선 환자 프로필 필드명 — missingInformation 과 같은 어휘의 여집합. */ patientFactors?: string[] }[];
  safetyAlerts: { severity: "INFO" | "WARNING" | "CRITICAL"; description: string; citations: { marker: number; evidenceId: string; guidelineTitle: string; guidelineVersion: string; sectionPath: string[]; quote: string; sourceUrl: string }[] }[];
  missingInformation: string[];
  reviewStatus: "DRAFT" | "ACCEPTED" | "MODIFIED" | "REJECTED";
  /** ISO 8601 */
  generatedAt: string;
};

dtsPropsFor.SocialLoginButtons:
/**
 * OAuth 콜백이 로그인 페이지로 되돌려 보낸 에러 코드. 지정하면 상단에 사용자 문구를 띄운다.
 * AUTH_OAUTH_DENIED | AUTH_OAUTH_STATE_MISMATCH | AUTH_OAUTH_EMAIL_MISSING |
 * AUTH_OAUTH_PROVIDER_UNSUPPORTED | AUTH_OAUTH_TICKET_INVALID | AUTH_OAUTH_FAILED
 */
error?: string;

dtsPropsFor.OnboardingForm:
/** 소셜 인증 후 발급된 가입 티켓. 이메일·소셜 신원은 서버가 티켓에서 꺼낸다. */
ticket: string;
/** 제공자에게서 받은 이름 — 이름 칸의 초기값이 된다. */
defaultDisplayName?: string;

dtsPropsFor.RequestGuidanceButton:
patientId: string;
/** 생성된 대화 id 로 이동하는 콜백. 미지정 시 /assistant?conversation={id} 로 전체 이동한다. */
onStarted?: (conversationId: string) => void;

dtsPropsFor.PatientCreateForm:
/** 등록 성공 시 생성된 환자 상세를 넘긴다. */
onCreated: (patient: {
  id: string;
  /** 비식별 케이스 라벨 (@example "CASE-001") */
  caseLabel: string;
  age?: number;
  sex?: "MALE" | "FEMALE" | "OTHER" | "UNKNOWN";
  bmi?: number;
  status: "ACTIVE" | "ARCHIVED";
  updatedAt: string;
  birthYear?: number;
  heightCm?: number;
  weightKg?: number;
  waistCm?: number;
  diagnoses: string[];
  medications: string[];
  allergies: string[];
  clinicalNotes?: string;
  /** 낙관적 잠금 버전 — 수정 요청에 그대로 실어 보낸다. */
  version: number;
}) => void;

dtsPropsFor.PatientListPanel:
/** 목록 항목을 선택했을 때. */
onSelect: (patient: {
  id: string;
  /** 비식별 케이스 라벨 (@example "CASE-001") */
  caseLabel: string;
  /** birthYear 기준 만 나이 근사 */
  age?: number;
  sex?: "MALE" | "FEMALE" | "OTHER" | "UNKNOWN";
  /** 소수 1자리 */
  bmi?: number;
  status: "ACTIVE" | "ARCHIVED";
  /** ISO 8601 */
  updatedAt: string;
}) => void;

dtsPropsFor.ConversationList:
/** 현재 선택된 대화 id. null 이면 선택 없음. */
selectedId: string | null;
onSelect: (conversation: {
  id: string;
  type: "GUIDELINE_QA" | "PATIENT_GUIDANCE";
  title: string;
  status: "ACTIVE" | "ARCHIVED";
  /** 마지막 메시지 미리보기 (80자) */
  lastMessagePreview?: string;
  /** 마지막 메시지 시각 (메시지가 없으면 대화 생성 시각) — 목록 정렬 키다. ISO 8601 */
  lastMessageAt: string;
}) => void;

dtsPropsFor.ChatPanel:
/** 메시지를 주고받을 대화 id. */
conversationId: string;
/** retrieval.completed 시 근거 패널(EvidenceInspector)로 넘길 근거 목록. */
onEvidenceChange?: (evidence: {
  id: string;
  guidelineId: string;
  guidelineVersionId: string;
  guidelineTitle: string;
  /** @example "2.0" */
  version: string;
  /** 지침 내 섹션 경로 — UI 에서 " > " 로 이어 붙인다. */
  sectionPath: string[];
  recommendationNumber?: string;
  /** 권고문 원문 (권고 청크인 경우) */
  recommendationText?: string;
  recommendationGrade?: { system: string; code: string; label: string };
  evidenceLevel?: { system: string; code: string; label: string };
  /** 본문 발췌 전문 */
  excerpt: string;
  pageStart?: number;
  pageEnd?: number;
  sourceUrl: string;
}[]) => void;
/** 답변 본문의 인용 마커 [n] 을 클릭했을 때. */
onSelectMarker?: (marker: number) => void;
/** 인용 마커 [n] 클릭 시 그 메시지의 인용 목록 전달 — 과거 저장분도 근거 패널이 복원한다. */
onShowCitations?: (citations: { marker: number; evidenceId: string; guidelineTitle: string; guidelineVersion: string; sectionPath: string[]; quote: string; sourceUrl: string }[], marker: number) => void;

dtsPropsFor.GuidelineListPanel:
/** 목록 항목을 선택했을 때. */
onSelect: (guideline: {
  id: string;
  /** @example "요통 한의표준임상진료지침" */
  title: string;
  /** @example "한국한의약진흥원" */
  publisher: string;
  /** @example "2.0" */
  currentVersion: string;
  /** 현재 버전 발행일 (ISO 8601) */
  publishedAt: string;
  status: "ACTIVE" | "SUPERSEDED";
}) => void;
